import{_ as d,o as a,c as r,a2 as i}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"उपभोक्ता संरक्षण कानून","description":"","frontmatter":{},"headers":[],"relativePath":"hi/42-消费者保护法.md","filePath":"hi/42-消费者保护法.md","lastUpdated":null}'),l={name:"hi/42-消费者保护法.md"};function e(o,t,h,n,s,b){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="उपभोक्ता-संरक्षण-कानून" tabindex="-1">उपभोक्ता संरक्षण कानून <a class="header-anchor" href="#उपभोक्ता-संरक्षण-कानून" aria-label="Permalink to &quot;उपभोक्ता संरक्षण कानून&quot;">​</a></h1><table tabindex="0"><thead><tr><th>मद</th><th>सामग्री</th></tr></thead><tbody><tr><td>दस्तावेज़ संख्या</td><td>42</td></tr><tr><td>मॉड्यूल</td><td>कानूनी प्रणाली और शासन-ढाँचा</td></tr><tr><td>कीवर्ड</td><td>उपभोक्ता अधिकार, निष्पक्ष व्यापार, धोखाधड़ी-विरोध, उत्पाद-दायित्व, सहजीवी बाज़ार</td></tr></tbody></table><h2 id="i-विधायी-उद्देश्य-और-लागू-क्षेत्र" tabindex="-1">I. विधायी उद्देश्य और लागू-क्षेत्र <a class="header-anchor" href="#i-विधायी-उद्देश्य-और-लागू-क्षेत्र" aria-label="Permalink to &quot;I. विधायी उद्देश्य और लागू-क्षेत्र&quot;">​</a></h2><p><em>उपभोक्ता संरक्षण कानून</em> लंगर सहजीवी सभ्यता की कानूनी प्रणाली के मुख्य कानूनों में से एक है। <em>सहजीवी श्रम कानून</em> के साथ मिलकर यह आर्थिक जीवन के दो मुख्य आधार बनाता है। यह कानून हेंग-ब्रह्मांड के भीतर सभी उपभोक्ताओं के वैध अधिकारों और हितों की रक्षा, बाज़ार-लेनदेन व्यवहारों का विनियमन, निष्पक्ष, ईमानदार, सहजीवी बाज़ार-व्यवस्था बनाए रखना और शिकारी व्यावसायिक व्यवहारों को सभी प्राणियों के अधिकारों का उल्लंघन करने से रोकना है।</p><p>यह कानून हेंग-ब्रह्मांड के भीतर उन सभी उपभोक्ताओं पर लागू होता है जो व्यक्तिगत या पारिवारिक जीवन-आवश्यकताओं की पूर्ति हेतु वस्तुएँ खरीदते या उपयोग करते हैं या सेवाएँ प्राप्त करते हैं, साथ ही उन संचालकों पर भी जो उपभोक्ताओं को वस्तुएँ या सेवाएँ प्रदान करते हैं। अंतर-पटल लेनदेन भी इसी कानून के अधीन हैं, किंतु पटल-भेदों के अनुसार कार्यान्वयन-नियम बनाए जा सकते हैं।</p><h2 id="ii-उपभोक्ताओं-के-मूल-अधिकार" tabindex="-1">II. उपभोक्ताओं के मूल अधिकार <a class="header-anchor" href="#ii-उपभोक्ताओं-के-मूल-अधिकार" aria-label="Permalink to &quot;II. उपभोक्ताओं के मूल अधिकार&quot;">​</a></h2><p>यह कानून स्थापित करता है कि उपभोक्ता निम्न नौ मूल अधिकारों का आनंद लेते हैं:</p><table tabindex="0"><thead><tr><th>अधिकार</th><th>अर्थ</th></tr></thead><tbody><tr><td>सुरक्षा-गारंटी अधिकार</td><td>उपभोक्ताओं को वस्तुएँ खरीदने, उपयोग करने और सेवाएँ प्राप्त करने पर व्यक्तिगत और संपत्ति-सुरक्षा को क्षति-रहित रखने का अधिकार</td></tr><tr><td>सत्य-जानकारी अधिकार</td><td>उपभोक्ताओं को खरीदी/उपयोग की वस्तुओं या प्राप्त सेवाओं की वास्तविक स्थिति जानने का अधिकार, जिसमें घटक, प्रभाव, जोखिम आदि शामिल</td></tr><tr><td>स्वतंत्र-चयन अधिकार</td><td>उपभोक्ताओं को वस्तुएँ या सेवाएँ स्वतंत्र रूप से चुनने, तुलना-पहचान-चयन करने, जबरन लेनदेन अस्वीकार करने का अधिकार</td></tr><tr><td>निष्पक्ष-लेनदेन अधिकार</td><td>उपभोक्ताओं को गुणवत्ता-गारंटी, उचित मूल्य, सटीक माप जैसी निष्पक्ष लेनदेन-शर्तें पाने का अधिकार</td></tr><tr><td>कानूनी-क्षतिपूर्ति अधिकार</td><td>वस्तुएँ खरीदने, उपयोग करने या सेवाएँ प्राप्त करने पर व्यक्तिगत या संपत्ति-क्षति झेलने वाले उपभोक्ताओं को कानूनानुसार क्षतिपूर्ति पाने का अधिकार</td></tr><tr><td>संगठन-अधिकार-रक्षा अधिकार</td><td>उपभोक्ताओं को कानूनानुसार उपभोक्ता-संगठन स्थापित करने या जुड़ने का अधिकार, अपने वैध हितों की रक्षा हेतु</td></tr><tr><td>ज्ञान-प्राप्ति अधिकार</td><td>उपभोक्ताओं को उपभोग और उपभोक्ता-अधिकार-संरक्षण से संबंधित ज्ञान और सूचना पाने का अधिकार</td></tr><tr><td>सम्मान-प्राप्ति अधिकार</td><td>वस्तुएँ खरीदते-उपयोग करते और सेवाएँ प्राप्त करते समय उपभोक्ताओं को व्यक्तिगत गरिमा और जातीय रीति-रिवाजों के सम्मान का अधिकार</td></tr><tr><td>निगरानी अधिकार</td><td>उपभोक्ताओं को वस्तुओं-सेवाओं तथा उपभोक्ता-अधिकार-संरक्षण कार्य की निगरानी और आलोचना-सुझाव देने का अधिकार</td></tr></tbody></table><h2 id="iii-संचालकों-के-दायित्व" tabindex="-1">III. संचालकों के दायित्व <a class="header-anchor" href="#iii-संचालकों-के-दायित्व" aria-label="Permalink to &quot;III. संचालकों के दायित्व&quot;">​</a></h2><p>उपभोक्ताओं को वस्तुएँ या सेवाएँ प्रदान करते समय संचालक निम्न दायित्व पूरे करेंगे:</p><ol><li><strong>वैध-संचालन दायित्व</strong>: संचालकों को संविधान और कानूनों का पालन करना होगा और अनुमोदित कार्यक्षेत्र में व्यावसायिक गतिविधियाँ करनी होंगी।</li><li><strong>सुरक्षा-गारंटी दायित्व</strong>: संचालकों को यह सुनिश्चित करना होगा कि प्रदत्त वस्तुएँ या सेवाएँ व्यक्ति और संपत्ति-सुरक्षा की आवश्यकताओं को पूरा करें; खतरे-योग्य वस्तुओं और सेवाओं के लिए सत्य स्पष्टीकरण और स्पष्ट चेतावनी देनी होगी।</li><li><strong>सत्य-सूचना दायित्व</strong>: संचालकों को वस्तुओं या सेवाओं के बारे में सत्य सूचना देनी होगी; झूठा या भ्रामक प्रचार नहीं करना होगा। साधना-प्रकार की वस्तुओं और सेवाओं को प्रभाव-सीमाएँ और संभावित जोखिम सत्य रूप से अंकित करने होंगे।</li><li><strong>गुणवत्ता-गारंटी दायित्व</strong>: संचालकों को यह सुनिश्चित करना होगा कि सामान्य उपयोग या सेवा-प्राप्ति में प्रदत्त वस्तुओं या सेवाओं में अपेक्षित गुणवत्ता, क्षमता, प्रयोजन और वैधता-अवधि हो।</li><li><strong>निष्पक्ष-लेनदेन दायित्व</strong>: संचालक मानक-खंडों, सूचनाओं, घोषणाओं, दुकान-सूचनाओं आदि के माध्यम से उपभोक्ता-अधिकारों को बहिष्कृत या सीमित करने, संचालक-दायित्व घटाने या मुक्त करने, उपभोक्ता-दायित्व बढ़ाने वाले अनुचित, अविवेकपूर्ण प्रावधान नहीं बना सकते।</li><li><strong>बिक्री-पश्चात सेवा दायित्व</strong>: संचालकों को राज्य-नियमों या उपभोक्ता-अनुबंधों के अनुसार मरम्मत, प्रतिस्थापन, वापसी और अन्य बिक्री-पश्चात सेवाओं का दायित्व वहन करना होगा।</li><li><strong>गोपनीयता-संरक्षण दायित्व</strong>: संचालकों को उपभोक्ताओं की व्यक्तिगत सूचना और चेतना-डेटा की रक्षा करनी होगी; उपभोक्ता की सहमति के बिना संग्रह, उपयोग या प्रकटीकरण नहीं किया जा सकता।</li></ol><h2 id="iv-विवाद-समाधान-और-कानूनी-दायित्व" tabindex="-1">IV. विवाद-समाधान और कानूनी दायित्व <a class="header-anchor" href="#iv-विवाद-समाधान-और-कानूनी-दायित्व" aria-label="Permalink to &quot;IV. विवाद-समाधान और कानूनी दायित्व&quot;">​</a></h2><p>उपभोक्ता और संचालक के बीच उपभोक्ता-अधिकार विवाद निम्न मार्गों से हल किया जा सकता है:</p><ul><li>संचालक के साथ बातचीत और समझौता</li><li>उपभोक्ता-संगठन से मध्यस्थता का अनुरोध</li><li>संबंधित प्रशासनिक विभाग में शिकायत</li><li>संचालक से हुई मध्यस्थता-संधि के अनुसार मध्यस्थता-संस्था से मध्यस्थता का अनुरोध</li><li>सहजीवी न्यायालय में मुकदमा दायर करना</li></ul><p>इस कानून के प्रावधानों का उल्लंघन कर उपभोक्ताओं के वैध अधिकारों और हितों का उल्लंघन करने वाले संचालक निम्न दायित्व वहन करेंगे:</p><table tabindex="0"><thead><tr><th>अवैध कृत्य</th><th>कानूनी दायित्व</th></tr></thead><tbody><tr><td>दोषपूर्ण वस्तुएँ या सेवाएँ देकर क्षति पहुँचाना</td><td>क्षतिपूर्ति-दायित्व वहन, जिसमें चिकित्सा-व्यय, कार्य-हानि क्षतिपूर्ति, विकलांगता-क्षतिपूर्ति आदि शामिल</td></tr><tr><td>धोखाधड़ी व्यवहार</td><td>उपभोक्ता की माँग पर क्षतिपूर्ति बढ़ाना, राशि खरीदी वस्तु की कीमत या प्राप्त सेवा-लागत का तीन गुना</td></tr><tr><td>झूठा प्रचार</td><td>अवैध कृत्य रोकने, प्रभाव समाप्त करने और जुर्माना भरने का आदेश</td></tr><tr><td>जबरन लेनदेन</td><td>सुधार का आदेश, अनुचित शुल्क वापसी और जुर्माना</td></tr><tr><td>उपभोक्ता गोपनीयता का उल्लंघन</td><td>मानसिक-क्षति क्षतिपूर्ति वहन; गंभीर परिस्थितियों में आपराधिक दायित्व</td></tr></tbody></table><h2 id="v-उपभोक्ता-संगठन-और-सामाजिक-निगरानी" tabindex="-1">V. उपभोक्ता-संगठन और सामाजिक निगरानी <a class="header-anchor" href="#v-उपभोक्ता-संगठन-और-सामाजिक-निगरानी" aria-label="Permalink to &quot;V. उपभोक्ता-संगठन और सामाजिक निगरानी&quot;">​</a></h2><p>राज्य सभी संगठनों और व्यक्तियों को उपभोक्ताओं के वैध अधिकारों को क्षति पहुँचाने वाले व्यवहारों पर सामाजिक निगरानी करने के लिए प्रोत्साहित और समर्थन करता है। उपभोक्ता-संघ कानूनानुसार स्थापित एक सामाजिक संगठन है जो वस्तुओं और सेवाओं पर सामाजिक निगरानी करता है और उपभोक्ताओं के वैध अधिकारों की रक्षा करता है, निम्न कार्य पूरे करता है:</p><ol><li>उपभोक्ताओं को उपभोग-सूचना और परामर्श-सेवाएँ प्रदान करना</li><li>संबंधित प्रशासनिक विभागों द्वारा वस्तुओं और सेवाओं की निगरानी, जाँच में भाग लेना</li><li>उपभोक्ताओं के वैध अधिकारों-हितों से संबंधित मामलों पर संबंधित प्रशासनिक विभागों को सूचित करना, पूछताछ करना, सुझाव देना</li><li>उपभोक्ताओं की शिकायतें स्वीकार करना, शिकायत-विषयों की जाँच और मध्यस्थता करना</li><li>उपभोक्ताओं के वैध अधिकारों को क्षति पहुँचाने वाले व्यवहारों के विरुद्ध क्षतिग्रस्त उपभोक्ताओं को मुकदमा दायर करने में समर्थन</li></ol><h2 id="निष्कर्ष" tabindex="-1">निष्कर्ष <a class="header-anchor" href="#निष्कर्ष" aria-label="Permalink to &quot;निष्कर्ष&quot;">​</a></h2><p><em>उपभोक्ता संरक्षण कानून</em> लंगर सहजीवी सभ्यता के बाज़ार-व्यवस्था का संरक्षक है। उपभोक्ताओं को पूर्ण अधिकार देकर, संचालकों के व्यवहार को बाँधकर, बहु-मार्गी विवाद-समाधान तंत्र स्थापित करके यह सुनिश्चित करता है कि बाज़ार-लेनदेन निष्पक्षता, ईमानदारी और सहजीवन की पटरी पर चलें, वाणिज्यिक क्षेत्र को शिकारी व्यवहारों का नया अड्डा बनने से रोकता है।</p><h2 id="संबंधित-दस्तावेज़" tabindex="-1">संबंधित दस्तावेज़ <a class="header-anchor" href="#संबंधित-दस्तावेज़" aria-label="Permalink to &quot;संबंधित दस्तावेज़&quot;">​</a></h2><ul><li>40-共生宪法总纲 (सहजीवी संविधान: सामान्य सिद्धांत)</li><li>41-共生劳动法 (सहजीवी श्रम कानून)</li><li>47-反垄断法 (एकाधिकार-विरोधी कानून)</li><li>36-社会结构与阶层流动 (सामाजिक संरचना और वर्ग-गतिशीलता)</li></ul>',23)])])}const p=d(l,[["render",e]]);export{_ as __pageData,p as default};
